using Acme.Mail;

var builder = WebApplication.CreateBuilder(args);
builder.Services.AddSingleton<SmtpSender>();

var app = builder.Build();

app.MapPost("/alerts", async (SmtpSender mail, CancellationToken ct) =>
{
    await mail.SendAsync("ops@example.com", "disk almost full", ct);
    return Results.Accepted();
});

app.Run();

using System.Net.Mail;

namespace Acme.Mail;

public sealed class SmtpSender(IConfiguration config)
{
    public async Task SendAsync(string to, string subject, CancellationToken ct)
    {
        var host = config["Smtp:Host"];
        var port = int.Parse(config["Smtp:Port"]!);
        var from = config["Smtp:From"]!;

        using var client = new SmtpClient(host, port);
        using var message = new MailMessage(from, to, subject, "");
        await client.SendMailAsync(message, ct);
    }
}

