using System.ComponentModel.DataAnnotations;

namespace Acme.Mail;

public sealed class SmtpOptions
{
    public const string Section = "Smtp";

    [Required]
    public string Host { get; set; } = "";

    [Range(1, 65535)]
    public int Port { get; set; }

    [Required, EmailAddress]
    public string From { get; set; } = "";
}

// src/Program.cs
builder.Services.AddOptions<SmtpOptions>()
    .BindConfiguration(SmtpOptions.Section)
    .ValidateDataAnnotations()
    .ValidateOnStart();

using System.Net.Mail;
using Microsoft.Extensions.Options;

namespace Acme.Mail;

public sealed class SmtpSender(IOptions<SmtpOptions> options)
{
    private readonly SmtpOptions _smtp = options.Value;

    public async Task SendAsync(string to, string subject, CancellationToken ct)
    {
        using var client = new SmtpClient(_smtp.Host, _smtp.Port);
        using var message = new MailMessage(_smtp.From, to, subject, "");
        await client.SendMailAsync(message, ct);
    }
}
